+  if (state.status === "completed") {
+    if (state.email && normalizeEmail(body.email) !== state.email) throw new M1Error(409);
+    return { status: state.status, userId: state.user_id };
+  }
+  if (state.status === "uninitialized" || !state.reservation_id) throw new M1Error(409);
+  if (body.reservationId && body.reservationId !== state.reservation_id) throw new M1Error(409);
+
+  const email = normalizeEmail(body.email);
+  if (state.email && state.email !== email) throw new M1Error(409);
+
+  if (!state.email) {
+    const claimedEmail = await environment.DB
+      .prepare(
+        `UPDATE bootstrap_state
+            SET email = ?, updated_at = ?
+          WHERE id = 1
+            AND status = 'reserved'
+            AND reservation_id = ?
+            AND (email IS NULL OR email = ?)
+          RETURNING email`,
+      )
+      .bind(email, Date.now(), state.reservation_id, email)
+      .first<{ email: string }>();
+    if (!claimedEmail) {
+      const racedState = await getBootstrapState(environment.DB);
+      if (racedState.email !== email) throw new M1Error(409);
+    }
+  }
+
+  const context = await auth.$context;
+  if (
+    body.password.length < context.password.config.minPasswordLength ||
+    body.password.length > context.password.config.maxPasswordLength
+  ) {
+    throw new M1Error(400);
+  }
+  const user = await ensureControlledUser(
+    auth,
+    email,
+    normalizeName(body.name, email),
+    body.password,
+    state.user_id,
+  );
+  const marked = await environment.DB
+    .prepare(
+      `UPDATE bootstrap_state
+          SET status = 'user-created', user_id = ?, user_created_at = COALESCE(user_created_at, ?), updated_at = ?
+        WHERE id = 1
+          AND status IN ('reserved', 'user-created')
+          AND reservation_id = ?
+          AND email = ?
+          AND (user_id IS NULL OR user_id = ?)
+        RETURNING user_id`,
+    )
+    .bind(user.id, Date.now(), Date.now(), state.reservation_id, email, user.id)
+    .first<{ user_id: string }>();
+  if (!marked) {
+    const racedState = await getBootstrapState(environment.DB);
+    if (racedState.user_id !== user.id) throw new M1Error(409);
+  }
+
+  const markedState = await getBootstrapState(environment.DB);
+  const principalId = await ensureHumanPrincipal(environment.DB, user.id, Date.now());
+  await completeBootstrapDomain(environment.DB, markedState, user, principalId, Date.now());
+  await sendVerificationEmail(auth, environment, user, request);
+
+  return { principalId, status: "completed" as const, userId: user.id };
+}
+
+async function readInvitation(database: D1Database, tokenHash: string) {
+  return database
+    .prepare(
+      `SELECT id, token_hash, email, name, status, expires_at,
+              invited_by_principal_id, claimed_user_id, claimed_principal_id, system_role_keys
+         FROM invitations
+        WHERE token_hash = ?
+        LIMIT 1`,
+    )
+    .bind(tokenHash)
+    .first<Invitation>();
+}
+
+async function markExpired(database: D1Database, invitationId: string, now: number) {
+  await database
+    .prepare(
+      `UPDATE invitations
+          SET status = 'expired', updated_at = ?
+        WHERE id = ? AND status = 'pending' AND expires_at <= ?`,
+    )
+    .bind(now, invitationId, now)
+    .run();
+}
+
+async function createInvitation(
+  environment: AuthEnvironment,
+  actor: Actor,
+  body: InvitationCreateBody,
+  request: Request,
+) {
+  await enforceRateLimit(environment, request, "invitation-create", 30, 60);
+  const email = normalizeEmail(body.email);
+  const name = body.name ? normalizeName(body.name, email) : null;
+  const requestedRoleKeys = await validateRoleKeys(environment.DB, body.systemRoleKeys ?? []);
+  const existingMapping = await environment.DB
+    .prepare(
+      `SELECT 1
+         FROM human_principals AS hp
+         JOIN principals AS p ON p.id = hp.principal_id
+         JOIN user AS u ON u.id = hp.user_id
+        WHERE u.email = ? AND p.status = 'active' AND hp.status = 'active' AND hp.disabled = 0
+        LIMIT 1`,
+    )
+    .bind(email)
+    .first<{ 1: number }>();
+  if (existingMapping) throw new M1Error(409);
+
+  const token = randomToken();
+  const tokenHash = await sha256Base64Url(token);
+  const invitationId = crypto.randomUUID();
+  const now = Date.now();
+  const requestedLifetime = body.expiresInSeconds ?? body.expiresIn ?? 60 * 60 * 24 * 7;
+  const expiresAt = now + requestedLifetime * 1000;
+
+  await environment.DB.batch([
+    environment.DB
+      .prepare(
+        `INSERT INTO invitations
+          (id, token_hash, email, name, status, expires_at, invited_by_principal_id, system_role_keys, created_at, updated_at)
+         VALUES (?, ?, ?, ?, 'pending', ?, ?, ?, ?, ?)`,
+      )
+      .bind(
+        invitationId,
+        tokenHash,
+        email,
+        name,
+        expiresAt,
+        actor.principalId,
+        JSON.stringify(requestedRoleKeys),
+        now,
+        now,
+      ),
+    auditStatement(
+      environment.DB,
+      `invitation:created:${invitationId}`,
+      "invitation.created",
+      actor.principalId,
+      null,
+      null,
+      { email, expiresAt },
+      now,
+    ),
+    outboxStatement(
+      environment.DB,
+      `invitation:created:outbox:${invitationId}`,
+      "invitation.created",
+      "invitation",
+      invitationId,
+      { email, expiresAt },
+      now,
+    ),
+  ]);
+
+  const url = `${environment.BETTER_AUTH_URL}/invite/${encodeURIComponent(token)}`;
+  recordDevelopmentEmail(environment, { email, kind: "invitation", token, url });
+  return { email, expiresAt, id: invitationId, token };
+}
+
+async function getPublicInvitation(
+  environment: AuthEnvironment,
+  token: string,
+  request: Request,
+) {
+  await enforceRateLimit(environment, request, "invitation-read", 60, 60);
+  const invitation = await readInvitation(environment.DB, await sha256Base64Url(token));
+  if (!invitation) throw new M1Error(404);
+  const now = Date.now();
+  if (invitation.status === "pending" && invitation.expires_at <= now) {
+    await markExpired(environment.DB, invitation.id, now);
+    throw new M1Error(404);
+  }
+  if (invitation.status !== "pending" && invitation.status !== "claimed") throw new M1Error(404);
+  return {
+    email: invitation.email,
+    expiresAt: invitation.expires_at,
+    name: invitation.name,
+    status: invitation.status,
+  };
+}
+
+async function claimInvitation(
+  environment: AuthEnvironment,
+  token: string,
+  body: InvitationAcceptBody,
+  request: Request,
+) {
+  await enforceRateLimit(environment, request, "invitation-accept", 30, 60);
+  const invitation = await readInvitation(environment.DB, await sha256Base64Url(token));
+  if (!invitation) throw new M1Error(404);
+  const now = Date.now();
+  const suppliedEmail = body.email ? normalizeEmail(body.email) : invitation.email;
+  if (suppliedEmail !== invitation.email) throw new M1Error(400);
+
+  let current = invitation;
+  if (current.status === "pending") {
+    if (current.expires_at <= now) {
+      await markExpired(environment.DB, current.id, now);
+      throw new M1Error(404);
+    }
+    const claimed = await environment.DB
+      .prepare(
+        `UPDATE invitations
+            SET status = 'claimed', claimed_at = ?, updated_at = ?
+          WHERE id = ? AND status = 'pending' AND expires_at > ?
+        RETURNING id, token_hash, email, name, status, expires_at,
+                  invited_by_principal_id, claimed_user_id, claimed_principal_id, system_role_keys`,
+      )
+      .bind(now, now, current.id, now)
+      .first<Invitation>();
+    current = claimed ?? (await readInvitation(environment.DB, current.token_hash)) ?? current;
+  }
+  if (current.status === "pending" || current.status === "expired" || current.status === "revoked") {
+    throw new M1Error(409);
+  }
+  if (current.status === "completed") throw new M1Error(409);
+
+  const context = await (await import("./auth").then(({ createAuth }) => createAuth(environment))).$context;
+  if (
+    body.password.length < context.password.config.minPasswordLength ||
+    body.password.length > context.password.config.maxPasswordLength
+  ) {
+    throw new M1Error(400);
+  }
+  // The caller supplies the auth instance through the route wrapper. This
+  // branch is replaced immediately by claimInvitationWithAuth below.
+  void context;
+  throw new M1Error(500);
+}
+
+async function claimInvitationWithAuth(
+  environment: AuthEnvironment,
+  auth: AuthInstance,
+  token: string,
+  body: InvitationAcceptBody,
+  request: Request,
+) {
+  await enforceRateLimit(environment, request, "invitation-accept", 30, 60);
+  const invitation = await readInvitation(environment.DB, await sha256Base64Url(token));
+  if (!invitation) throw new M1Error(404);
+  const now = Date.now();
+  const suppliedEmail = body.email ? normalizeEmail(body.email) : invitation.email;
+  if (suppliedEmail !== invitation.email) throw new M1Error(400);
+
+  let current = invitation;
+  if (current.status === "pending") {
+    if (current.expires_at <= now) {
+      await markExpired(environment.DB, current.id, now);
+      throw new M1Error(404);
+    }
+    const claimed = await environment.DB
+      .prepare(
+        `UPDATE invitations
+            SET status = 'claimed', claimed_at = ?, updated_at = ?
+          WHERE id = ? AND status = 'pending' AND expires_at > ?
+        RETURNING id, token_hash, email, name, status, expires_at,
+                  invited_by_principal_id, claimed_user_id, claimed_principal_id, system_role_keys`,
+      )
+      .bind(now, now, current.id, now)
+      .first<Invitation>();
+    current = claimed ?? (await readInvitation(environment.DB, current.token_hash)) ?? current;
+  }
+  if (current.status === "pending" || current.status === "expired" || current.status === "revoked") {
+    throw new M1Error(409);
+  }
+  if (current.status === "completed") throw new M1Error(409);
+
+  const context = await auth.$context;
+  if (
+    body.password.length < context.password.config.minPasswordLength ||
+    body.password.length > context.password.config.maxPasswordLength
+  ) {
+    throw new M1Error(400);
+  }
+  const user = await ensureControlledUser(
+    auth,
+    current.email,
+    normalizeName(body.name, current.name ?? current.email),
+    body.password,
+    current.claimed_user_id,
+  );
+  const marked = await environment.DB
+    .prepare(
+      `UPDATE invitations
+          SET claimed_user_id = ?, updated_at = ?
+        WHERE id = ? AND status = 'claimed'
+          AND (claimed_user_id IS NULL OR claimed_user_id = ?)
+        RETURNING claimed_user_id`,
+    )
+    .bind(user.id, Date.now(), current.id, user.id)
+    .first<{ claimed_user_id: string }>();
+  if (!marked) {
+    const racedInvitation = await readInvitation(environment.DB, current.token_hash);
+    if (!racedInvitation || racedInvitation.claimed_user_id !== user.id) throw new M1Error(409);
+    current = racedInvitation;
+  } else {
+    current = (await readInvitation(environment.DB, current.token_hash)) ?? current;
+  }
+  if (current.status !== "claimed") throw new M1Error(409);
+
+  const principalId = await ensureHumanPrincipal(environment.DB, user.id, Date.now());
+  const roleKeys = await validateRoleKeys(
+    environment.DB,
+    roleKeysFromStorage(current.system_role_keys),
+  );
+  const eventId = `invitation:completed:${current.id}`;
+  const completedAt = Date.now();
+  const statements = [
+    ...roleKeys.map((roleKey) => grantRoleStatement(
+      environment.DB,
+      principalId,
+      roleKey,
+      current.invited_by_principal_id,
+      completedAt,
+    )),
+    environment.DB
+      .prepare(
+        `UPDATE invitations
+            SET status = 'completed', claimed_principal_id = ?, completed_at = ?, updated_at = ?
+          WHERE id = ? AND status = 'claimed' AND claimed_user_id = ?`,
+      )
+      .bind(principalId, completedAt, completedAt, current.id, user.id),
+    auditStatement(
+      environment.DB,
+      eventId,
+      "invitation.completed",
+      current.invited_by_principal_id,
+      principalId,
+      user.id,
+      { email: current.email },
+      completedAt,
+    ),
+    outboxStatement(
+      environment.DB,
+      `invitation:completed:outbox:${current.id}`,
+      "invitation.completed",
+      "invitation",
+      current.id,
+      { principalId, userId: user.id },
+      completedAt,
+    ),
+  ];
+  await environment.DB.batch(statements);
+  await sendVerificationEmail(auth, environment, user, request);
+  return {
+    email: user.email,
+    principalId,
+    status: "accepted" as const,
+    userId: user.id,
+  };
+}
+
+async function resolveInvitationForRevoke(database: D1Database, identifier: string) {
+  const byId = await database
+    .prepare("SELECT id, status FROM invitations WHERE id = ? LIMIT 1")
+    .bind(identifier)
+    .first<{ id: string; status: InvitationStatus }>();
+  if (byId) return byId;
+  const tokenHash = await sha256Base64Url(identifier);
+  return database
+    .prepare("SELECT id, status FROM invitations WHERE token_hash = ? LIMIT 1")
+    .bind(tokenHash)
+    .first<{ id: string; status: InvitationStatus }>();
+}
+
+async function revokeInvitation(
+  environment: AuthEnvironment,
+  actor: Actor,
+  identifier: string,
+  request: Request,
+) {
+  await enforceRateLimit(environment, request, "invitation-revoke", 30, 60);
+  const invitation = await resolveInvitationForRevoke(environment.DB, identifier);
+  if (!invitation) throw new M1Error(404);
+  const now = Date.now();
+  const result = await environment.DB
+    .prepare(
+      `UPDATE invitations
+          SET status = 'revoked', revoked_at = ?, updated_at = ?
+        WHERE id = ? AND status IN ('pending', 'claimed')
+        RETURNING id`,
+    )
+    .bind(now, now, invitation.id)
+    .first<{ id: string }>();
+  if (result) {
+    await environment.DB.batch([
+      auditStatement(
+        environment.DB,
+        `invitation:revoked:${invitation.id}`,
+        "invitation.revoked",
+        actor.principalId,
+        null,
+        null,
+        { invitationId: invitation.id },
+        now,
+      ),
+      outboxStatement(
+        environment.DB,
+        `invitation:revoked:outbox:${invitation.id}`,
+        "invitation.revoked",
+        "invitation",
+        invitation.id,
+        {},
+        now,
+      ),
+    ]);
+  }
+  return { id: invitation.id, status: "revoked" as const };
+}
+
+async function resolveHumanPrincipal(database: D1Database, identifier: string) {
+  return database
+    .prepare(
+      `SELECT p.id AS principal_id, p.status AS principal_status,
+              hp.user_id, hp.status AS human_status, hp.disabled,
+              EXISTS(
+                SELECT 1
+                  FROM system_role_grants AS g
+                  JOIN system_roles AS r ON r.id = g.role_id
+                 WHERE g.principal_id = p.id
+                   AND g.revoked_at IS NULL
+                   AND r.key = 'root'
+              ) AS is_root
+         FROM principals AS p
+         JOIN human_principals AS hp ON hp.principal_id = p.id
+        WHERE p.id = ? OR hp.user_id = ?
+        LIMIT 1`,
+    )
+    .bind(identifier, identifier)
+    .first<{
+      principal_id: string;
+      principal_status: "active" | "disabled";
+      user_id: string;
+      human_status: "active" | "disabled";
+      disabled: number;
+      is_root: number;
+    }>();
+}
+
+async function activeRootCount(database: D1Database) {
+  const row = await database
+    .prepare(
+      `SELECT COUNT(*) AS count
+         FROM principals AS p
+         JOIN human_principals AS hp ON hp.principal_id = p.id
+         JOIN system_role_grants AS g ON g.principal_id = p.id
+         JOIN system_roles AS r ON r.id = g.role_id
+        WHERE p.type = 'human'
+          AND p.status = 'active'
+          AND hp.status = 'active'
+          AND hp.disabled = 0
+          AND g.revoked_at IS NULL
+          AND r.key = 'root'`,
+    )
+    .first<{ count: number }>();
+  return row?.count ?? 0;
+}
+
+async function setUserDisabled(
+  environment: AuthEnvironment,
+  actor: Actor,
+  identifier: string,
+  disabled: boolean,
+  request: Request,
+) {
+  await enforceRateLimit(environment, request, disabled ? "user-disable" : "user-enable", 60, 60);
+  const target = await resolveHumanPrincipal(environment.DB, identifier);
+  if (!target) throw new M1Error(404);
+  if (target.principal_status === (disabled ? "disabled" : "active") &&
+      target.human_status === (disabled ? "disabled" : "active")) {
+    return { status: disabled ? "disabled" as const : "active" as const, userId: target.user_id };
+  }
+  if (disabled && target.is_root === 1 && (await activeRootCount(environment.DB)) <= 1) {
+    throw new M1Error(409);
+  }
+
+  const now = Date.now();
+  const nextStatus = disabled ? "disabled" : "active";
+  const result = await environment.DB
+    .prepare(
+      disabled
+        ? `UPDATE principals
+              SET status = 'disabled', disabled_at = ?, updated_at = ?
+            WHERE id = ? AND type = 'human' AND status = 'active'
+              AND (
+                NOT EXISTS (
+                  SELECT 1
+                    FROM system_role_grants AS own_grant
+                    JOIN system_roles AS own_role ON own_role.id = own_grant.role_id
+                   WHERE own_grant.principal_id = principals.id
+                     AND own_grant.revoked_at IS NULL
+                     AND own_role.key = 'root'
+                )
+                OR (
+                  SELECT COUNT(*)
+                    FROM principals AS root_principal
+                    JOIN human_principals AS root_human ON root_human.principal_id = root_principal.id
+                    JOIN system_role_grants AS root_grant ON root_grant.principal_id = root_principal.id
+                    JOIN system_roles AS root_role ON root_role.id = root_grant.role_id
+                   WHERE root_principal.type = 'human'
+                     AND root_principal.status = 'active'
+                     AND root_human.status = 'active'
+                     AND root_human.disabled = 0
+                     AND root_grant.revoked_at IS NULL
+                     AND root_role.key = 'root'
+                ) > 1
+              )
+            RETURNING id`
+        : `UPDATE principals
+              SET status = 'active', disabled_at = NULL, updated_at = ?
+            WHERE id = ? AND type = 'human' AND status = 'disabled'
+            RETURNING id`,
+    )
+    .bind(...(disabled ? [now, now, target.principal_id] : [now, target.principal_id]))
+    .first<{ id: string }>();
+
+  if (!result) {
+    const current = await resolveHumanPrincipal(environment.DB, identifier);
+    if (current?.principal_status === nextStatus && current.human_status === nextStatus) {
+      return { status: disabled ? "disabled" as const : "active" as const, userId: current.user_id };
+    }
+    throw new M1Error(409);
+  }
+
+  const statements = [
+    environment.DB
+      .prepare(
+        `UPDATE human_principals
+            SET status = ?, disabled = ?, disabled_at = ?, updated_at = ?
+          WHERE principal_id = ?`,
+      )
+      .bind(nextStatus, disabled ? 1 : 0, disabled ? now : null, now, target.principal_id),
+    auditStatement(
+      environment.DB,
+      `user:${disabled ? "disabled" : "enabled"}:${target.principal_id}:${now}`,
+      `user.${disabled ? "disabled" : "enabled"}`,
+      actor.principalId,
+      target.principal_id,
+      target.user_id,
+      {},
+      now,
+    ),
+    outboxStatement(
+      environment.DB,
+      `user:${disabled ? "disabled" : "enabled"}:outbox:${target.principal_id}:${now}`,
+      `user.${disabled ? "disabled" : "enabled"}`,
+      "principal",
+      target.principal_id,
+      { userId: target.user_id, status: nextStatus },
+      now,
+    ),
+  ];
+  await environment.DB.batch(statements);
+
+  if (disabled) {
+    const context = await authForSessionRevocation(environment);
+    await context.internalAdapter.deleteUserSessions(target.user_id);
+  }
+
+  return { status: disabled ? "disabled" as const : "active" as const, userId: target.user_id };
+}
+
+async function authForSessionRevocation(environment: AuthEnvironment) {
+  const { createAuth } = await import("./auth");
+  return (await createAuth(environment).$context).internalAdapter;
+}
+
+export function createM1Routes(environment: AuthEnvironment, auth: AuthInstance) {
+  return new Elysia({ name: "shui-m1-routes" })
+    .onBeforeHandle(({ set }) => {
+      set.headers["cache-control"] = "no-store";
+      set.headers.pragma = "no-cache";
+    })
+    .onError(({ code, error, set }) => {
+      set.headers["cache-control"] = "no-store";
+      set.headers.pragma = "no-cache";
+      const statusCode = error instanceof M1Error
+        ? error.statusCode
+        : code === "VALIDATION"
+          ? 400
+          : 500;
+      set.status = statusCode;
+      return {
+        error: statusCode >= 500 ? "Request failed." : "The request could not be completed.",
+      };
+    })
+    .get("/bootstrap", () => getBootstrapStatus(environment))
+    .get("/setup", () => getBootstrapStatus(environment))
+    .post(
+      "/bootstrap/reserve",
+      ({ body, request }) => reserveBootstrap(environment, body, request),
+      { body: bootstrapTokenBodySchema },
+    )
+    .post(
+      "/setup/reserve",
+      ({ body, request }) => reserveBootstrap(environment, body, request),
+      { body: bootstrapTokenBodySchema },
+    )
+    .post(
+      "/bootstrap/complete",
+      ({ body, request }) => completeBootstrap(environment, auth, body, request),
+      { body: bootstrapCompleteBodySchema },
+    )
+    .post(
+      "/setup/complete",
+      ({ body, request }) => completeBootstrap(environment, auth, body, request),
+      { body: bootstrapCompleteBodySchema },
+    )
+    .post(
+      "/invitations",
+      ({ body, request }) => requireRole(auth, environment, request, ["root"])
+        .then((actor) => createInvitation(environment, actor, body, request)),
+      { body: invitationCreateBodySchema },
+    )
+    .get(
+      "/invitations/:token",
+      ({ params, request }) => getPublicInvitation(environment, params.token, request),
+      { params: tokenParamsSchema },
+    )
+    .post(
+      "/invitations/:token/accept",
+      ({ body, params, request }) => claimInvitationWithAuth(environment, auth, params.token, body, request),
+      { body: invitationAcceptBodySchema, params: tokenParamsSchema },
+    )
+    .post(
+      "/invitations/:token/claim",
+      ({ body, params, request }) => claimInvitationWithAuth(environment, auth, params.token, body, request),
+      { body: invitationAcceptBodySchema, params: tokenParamsSchema },
+    )
+    .post(
+      "/invitations/:token/complete",
+      ({ body, params, request }) => claimInvitationWithAuth(environment, auth, params.token, body, request),
+      { body: invitationAcceptBodySchema, params: tokenParamsSchema },
+    )
+    .post(
+      "/invitations/:identifier/revoke",
+      ({ params, request }) => requireRole(auth, environment, request, ["root"])
+        .then((actor) => revokeInvitation(environment, actor, params.identifier, request)),
+      { params: identifierParamsSchema },
+    )
+    .post(
+      "/users/:id/disable",
+      ({ params, request }) => requireRole(auth, environment, request, ["root", "user-admin"])
+        .then((actor) => setUserDisabled(environment, actor, params.id, true, request)),
+      { params: userParamsSchema },
+    )
+    .post(
